"""
Flask Todo API — flat-file storage with JWT authentication.

A single-file Flask app with clean structure: routes and error handling,
backed by a repository data-access layer. All data is stored in a JSON
flat file (no databases).

Endpoints:
  POST /auth/register   -> create a user
  POST /auth/login      -> issue a JWT
  /tasks/*              -> require a valid JWT (owner-scoped)
"""

import functools
import os
import threading
from datetime import datetime, timedelta

import jwt
from flask import Flask, g, jsonify, request
from werkzeug.security import generate_password_hash

from email_tasks import send_notification_email
from repositories import TaskRepository, UserRepository

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get(
    "SECRET_KEY", "dev-secret-key-for-local-development-only"
)

DATA_FILE = os.environ.get("DATA_FILE", "tasks.json")
TOKEN_TTL = timedelta(hours=12)
_lock = threading.Lock()

task_repo = TaskRepository(data_file=lambda: DATA_FILE, lock=_lock)
user_repo = UserRepository(data_file=lambda: DATA_FILE, lock=_lock)


def init_store() -> None:
    with _lock:
        if not os.path.exists(DATA_FILE):
            user_repo.write_store(
                {"tasks": [], "next_id": 1, "users": [], "next_user_id": 1}
            )
        else:
            store = user_repo.read_store()
            if _migrate(store):
                user_repo.write_store(store)


def _migrate(store: dict) -> bool:
    """Bring old stores up to date without destroying existing data."""
    changed = False
    if "users" not in store:
        store["users"] = []
        changed = True
    if "next_user_id" not in store:
        store["next_user_id"] = 1
        changed = True

    ownerless = [
        t for t in store.get("tasks", [])
        if t.get("owner_id") is None
    ]
    if ownerless:
        legacy = next(
            (u for u in store["users"] if u["username"] == "legacy"), None
        )
        if legacy is None:
            legacy = {
                "id": store["next_user_id"],
                "username": "legacy",
                "email": "legacy@example.com",
                "password_hash": generate_password_hash("legacy"),
            }
            store["next_user_id"] += 1
            store["users"].append(legacy)
        for task in ownerless:
            task["owner_id"] = legacy["id"]
        changed = True
    return changed


# ── Auth helpers ───────────────────────────────────────────────

def token_for(user: dict) -> str:
    payload = {
        "sub": str(user["id"]),
        "username": user["username"],
        "exp": datetime.utcnow() + TOKEN_TTL,
    }
    return jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")


def auth_required(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        header = request.headers.get("Authorization", "")
        token = header[7:] if header.startswith("Bearer ") else None
        if not token:
            return jsonify({"error": "missing or invalid token"}), 401
        try:
            payload = jwt.decode(
                token, app.config["SECRET_KEY"], algorithms=["HS256"]
            )
        except jwt.PyJWTError:
            return jsonify({"error": "missing or invalid token"}), 401
        user = user_repo.get(int(payload.get("sub")))
        if user is None:
            return jsonify({"error": "missing or invalid token"}), 401
        g.current_user = user
        return func(*args, **kwargs)

    return wrapper


# ── Routes: Auth ───────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    email = data.get("email")
    if not isinstance(username, str) or not username.strip():
        return jsonify({"error": "username is required"}), 400
    if not isinstance(password, str) or not password:
        return jsonify({"error": "password is required"}), 400
    user = user_repo.create_user(username.strip(), password, email=email)
    if user is None:
        return jsonify({"error": "username already exists"}), 409
    return jsonify({"id": user["id"], "username": user["username"], "token": token_for(user)}), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"error": "username and password are required"}), 400
    user = user_repo.verify_user(username, password)
    if user is None:
        return jsonify({"error": "invalid credentials"}), 401
    return jsonify({"token": token_for(user)})


# ── Routes: Tasks ──────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
@auth_required
def list_tasks():
    return jsonify(task_repo.list_for_owner(g.current_user["id"]))


@app.route("/tasks", methods=["POST"])
@auth_required
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    task = task_repo.create_task(title.strip(), g.current_user["id"])
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@auth_required
def show_task(task_id: int):
    task = task_repo.get_for_owner(task_id, g.current_user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@auth_required
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    current = task_repo.get_for_owner(task_id, g.current_user["id"])
    if current is None:
        return jsonify({"error": "task not found"}), 404
    task = task_repo.update(
        task_id,
        g.current_user["id"],
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if task["status"] == "completed" and current["status"] != "completed":
        user = g.current_user
        user_email = user.get("email") or f"{user['username']}@example.com"
        send_notification_email.delay(user_email, task["title"])
    return jsonify(task)


if __name__ == "__main__":
    init_store()
    app.run(debug=True)

"""
Repository pattern for the Todo API data layer.

All access to the underlying storage (a JSON flat file) happens through
repository classes. Route handlers never touch storage directly.
"""

import json
import os
import threading
from abc import ABC, abstractmethod
from datetime import datetime

from werkzeug.security import check_password_hash, generate_password_hash


class BaseRepository(ABC):
    """Abstract base repository providing common CRUD operations."""

    def __init__(self, data_file=None, lock=None):
        if callable(data_file):
            self._data_file_provider = data_file
        else:
            path = data_file or os.environ.get("DATA_FILE", "tasks.json")
            self._data_file_provider = lambda: path
        self._lock = lock if lock is not None else threading.Lock()

    def _data_file(self) -> str:
        return self._data_file_provider()

    def read_store(self) -> dict:
        with open(self._data_file()) as f:
            return json.load(f)

    def write_store(self, store: dict) -> None:
        with open(self._data_file(), "w") as f:
            json.dump(store, f, indent=2)

    @property
    @abstractmethod
    def entity_name(self) -> str:
        """Collection name within the store."""

    @property
    @abstractmethod
    def next_id_key(self) -> str:
        """Store key tracking the next id for this entity."""

    def get(self, entity_id: int) -> dict | None:
        store = self.read_store()
        for item in store.get(self.entity_name, []):
            if item["id"] == entity_id:
                return item
        return None

    def all(self) -> list:
        store = self.read_store()
        return store.get(self.entity_name, [])

    def create(self, item: dict, conflict_checker=None) -> dict | None:
        with self._lock:
            store = self.read_store()
            if conflict_checker is not None and conflict_checker(store, item):
                return None
            item["id"] = store[self.next_id_key]
            store[self.entity_name].append(item)
            store[self.next_id_key] += 1
            self.write_store(store)
            return item


class TaskRepository(BaseRepository):
    """Persistence for tasks, scoped by owner."""

    @property
    def entity_name(self) -> str:
        return "tasks"

    @property
    def next_id_key(self) -> str:
        return "next_id"

    def create_task(self, title: str, owner_id: int) -> dict:
        task = {
            "title": title,
            "status": "pending",
            "owner_id": owner_id,
            "created_at": datetime.utcnow().isoformat(),
        }
        return self.create(task)

    def list_for_owner(self, owner_id: int) -> list:
        store = self.read_store()
        mine = [t for t in store["tasks"] if t.get("owner_id") == owner_id]
        return sorted(mine, key=lambda t: t["created_at"], reverse=True)

    def get_for_owner(self, task_id: int, owner_id: int) -> dict | None:
        store = self.read_store()
        for task in store["tasks"]:
            if task["id"] == task_id and task.get("owner_id") == owner_id:
                return task
        return None

    def update(
        self,
        task_id: int,
        owner_id: int,
        title: str | None = None,
        status: str | None = None,
    ) -> dict | None:
        with self._lock:
            store = self.read_store()
            for task in store["tasks"]:
                if task["id"] == task_id and task.get("owner_id") == owner_id:
                    if title is not None:
                        task["title"] = title
                    if status is not None:
                        task["status"] = status
                    self.write_store(store)
                    return task
        return None


class UserRepository(BaseRepository):
    """Persistence for users and authentication lookups."""

    @property
    def entity_name(self) -> str:
        return "users"

    @property
    def next_id_key(self) -> str:
        return "next_user_id"

    def create_user(self, username: str, password: str, email: str | None = None) -> dict | None:
        user = {
            "username": username,
            "email": email or f"{username}@example.com",
            "password_hash": generate_password_hash(password),
        }
        return self.create(
            user,
            conflict_checker=lambda store, item: any(
                u["username"] == item["username"] for u in store["users"]
            ),
        )

    def get_by_username(self, username: str) -> dict | None:
        store = self.read_store()
        for user in store["users"]:
            if user["username"] == username:
                return user
        return None

    def verify_user(self, username: str, password: str) -> dict | None:
        user = self.get_by_username(username)
        if user is None or not check_password_hash(user["password_hash"], password):
            return None
        return user

